<?php
declare(strict_types=1);require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/lacms_security.php';requireLacmsPermission('lacms.activity_logs.view');$pdo=db();$where=['al.system_id=:system'];$params=[':system'=>lacmsSystemId()];$search=clean($_GET['search']??'');if($search!==''){$where[]='(al.action LIKE :s1 OR al.details LIKE :s2 OR u.full_name LIKE :s3)';$like='%'.$search.'%';$params[':s1']=$like;$params[':s2']=$like;$params[':s3']=$like;}$q=$pdo->prepare('SELECT al.*,u.full_name,u.email FROM activity_logs al LEFT JOIN users u ON u.id=al.user_id WHERE '.implode(' AND ',$where).' ORDER BY al.created_at DESC,al.id DESC LIMIT 1000');$q->execute($params);$rows=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><title>LACMS Activity Logs</title><style>body{font:10px Arial;margin:20px}.head{text-align:center;border-bottom:3px solid #0f2137;margin-bottom:12px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #bbb;padding:4px;vertical-align:top}th{background:#eee}</style></head><body onload="window.print()"><div class="head"><h2>LACMS Activity Logs</h2><p>Generated <?= date('F j, Y g:i A') ?></p></div><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Details</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['created_at']) ?></td><td><?= e($r['full_name']?:'System') ?><br><?= e($r['email']?:'') ?></td><td><?= e($r['action']) ?></td><td><?= e($r['details']?:'') ?></td><td><?= e($r['ip_address']?:'') ?></td></tr><?php endforeach; ?></tbody></table></body></html>
